131	export async function updateAllUpdatableExtensions(
132	  extensions: GeminiCLIExtension[],
133	  extensionsState: Map<string, ExtensionUpdateStatus>,
134	  extensionManager: ExtensionManager,
135	  dispatch: (action: ExtensionUpdateAction) => void,
136	  enableExtensionReloading?: boolean,
137	): Promise<ExtensionUpdateInfo[]> {
138	  return (
139	    await Promise.all(
140	      extensions
141	        .filter(
142	          (extension) =>
143	            extensionsState.get(extension.name)?.status ===
144	            ExtensionUpdateState.UPDATE_AVAILABLE,
145	        )
146	        .map((extension) =>
147	          updateExtension(
148	            extension,
149	            extensionManager,
150	            extensionsState.get(extension.name)!.status,
151	            dispatch,
152	            enableExtensionReloading,
153	          ),
154	        ),
155	    )
156	  ).filter((updateInfo) => !!updateInfo);
157	}
