14	export class FileKeychain implements Keychain {
15	  private readonly tokenFilePath: string;
16	  private readonly encryptionKey: Buffer;
17	
18	  constructor() {
19	    const configDir = path.join(homedir(), GEMINI_DIR);
20	    this.tokenFilePath = path.join(configDir, 'gemini-credentials.json');
21	    this.encryptionKey = this.deriveEncryptionKey();
22	  }
23	
24	  private deriveEncryptionKey(): Buffer {
25	    const salt = `${os.hostname()}-${os.userInfo().username}-gemini-cli`;
26	    return crypto.scryptSync('gemini-cli-oauth', salt, 32);
27	  }
28	
29	  private encrypt(text: string): string {
30	    const iv = crypto.randomBytes(16);
31	    const cipher = crypto.createCipheriv('aes-256-gcm', this.encryptionKey, iv);
32	
33	    let encrypted = cipher.update(text, 'utf8', 'hex');
34	    encrypted += cipher.final('hex');
35	
36	    const authTag = cipher.getAuthTag();
37	
38	    return iv.toString('hex') + ':' + authTag.toString('hex') + ':' + encrypted;
39	  }
40	
41	  private decrypt(encryptedData: string): string {
42	    const parts = encryptedData.split(':');
43	    if (parts.length !== 3) {
44	      throw new Error('Invalid encrypted data format');
45	    }
46	
47	    const iv = Buffer.from(parts[0], 'hex');
48	    const authTag = Buffer.from(parts[1], 'hex');
49	    const encrypted = parts[2];
50	
51	    const decipher = crypto.createDecipheriv(
52	      'aes-256-gcm',
53	      this.encryptionKey,
54	      iv,
55	    );
56	    decipher.setAuthTag(authTag);
57	
58	    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
59	    decrypted += decipher.final('utf8');
60	
61	    return decrypted;
62	  }
63	
64	  private async ensureDirectoryExists(): Promise<void> {
65	    const dir = path.dirname(this.tokenFilePath);
66	    await fs.mkdir(dir, { recursive: true, mode: 0o700 });
67	  }
68	
69	  private async loadData(): Promise<Record<string, Record<string, string>>> {
70	    try {
71	      const data = await fs.readFile(this.tokenFilePath, 'utf-8');
72	      const decrypted = this.decrypt(data);
73	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
74	      return JSON.parse(decrypted) as Record<string, Record<string, string>>;
75	    } catch (error: unknown) {
76	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
