110	  async setPassword(
111	    service: string,
112	    account: string,
113	    password: string,
114	  ): Promise<void> {
115	    const data = await this.loadData();
116	    if (!data[service]) {
117	      data[service] = {};
118	    }
119	    data[service][account] = password;
120	    await this.saveData(data);
121	  }
122	
123	  async deletePassword(service: string, account: string): Promise<boolean> {
124	    const data = await this.loadData();
125	    if (data[service] && account in data[service]) {
126	      delete data[service][account];
127	
128	      if (Object.keys(data[service]).length === 0) {
129	        delete data[service];
130	      }
131	
132	      if (Object.keys(data).length === 0) {
133	        try {
134	          await fs.unlink(this.tokenFilePath);
135	        } catch (error: unknown) {
136	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
137	          const err = error as NodeJS.ErrnoException;
138	          if (err.code !== 'ENOENT') {
139	            throw error;
140	          }
141	        }
142	      } else {
143	        await this.saveData(data);
144	      }
145	      return true;
146	    }
147	    return false;
148	  }
