150	  async findCredentials(
151	    service: string,
152	  ): Promise<Array<{ account: string; password: string }>> {
153	    const data = await this.loadData();
154	    const serviceData = data[service] || {};
155	    return Object.entries(serviceData).map(([account, password]) => ({
156	      account,
157	      password,
158	    }));
159	  }
