export enum IntegrityDataStatus {
  /** The recorded signature matches the provided metadata. */
  VERIFIED = 'verified',
  /** No integrity data has been recorded for the extension. */
  MISSING = 'missing',
  /** Integrity data exists but does not match, indicating tampering. */
  INVALID = 'invalid',
